const KEY: (&str, &str) = ("OPENAI_API_KEY", "sk-test-synthetic-000");
const THEMES: [&str; 8] =
    ["navy_fleet", "air_bomber", "army_tanks", "industry_factory", "politics_party", "research_science", "economy_trade", "intelligence_spy"];

/// A focus-sized (100x88) round plaque with a little texture; `i` varies its size and shade.
fn plaque(i: u32) -> Rgba {
    let mut img = Rgba::new(100, 88);
    let r = 30.0 + f64::from(i % 7);
    let shade = 90 + (i * 13 % 60) as u8;
    for y in 0..88u32 {
        for x in 0..100u32 {
            let d = ((f64::from(x) - 50.0).powi(2) + (f64::from(y) - 44.0).powi(2)).sqrt();
            if d < r {
                let v = if d > r - 4.0 { 40 } else { shade.wrapping_add(((x * 3 + y * i) % 23) as u8) };
                img.set_px(x, y, [v, v.saturating_sub(10), v / 2, 255]);
            }
        }
    }
    img
}

/// A fake game: 6 generic focus icons per theme, 10 Japanese and 10 German ones, the tag list and country names.
fn fake_focus_game() -> tempfile::TempDir {
    let game = tempfile::Builder::new().prefix("g").tempdir_in(repo_work_dir()).unwrap();
    let goals = game.path().join("gfx/interface/goals");
    std::fs::create_dir_all(&goals).unwrap();
    let mut i = 0u32;
    for theme in THEMES {
        for k in 0..6 {
            std::fs::write(goals.join(format!("goal_generic_{theme}_{k}.dds")), dds::write_a8r8g8b8(&plaque(i))).unwrap();
            i += 1;
        }
    }
    for k in 0..10 {
        std::fs::write(goals.join(format!("focus_JAP_imperial_navy_{k}.dds")), dds::write_a8r8g8b8(&plaque(i))).unwrap();
        i += 1;
        std::fs::write(goals.join(format!("focus_GER_army_{k}.dds")), dds::write_a8r8g8b8(&plaque(i))).unwrap();
        i += 1;
    }
    let tags = game.path().join("common/country_tags");
    std::fs::create_dir_all(&tags).unwrap();
    std::fs::write(tags.join("00_countries.txt"), "GER = \"countries/Germany.txt\"\nJAP = \"countries/Japan.txt\"\n").unwrap();
    let loc = game.path().join("localisation/english");
    std::fs::create_dir_all(&loc).unwrap();
    std::fs::write(
        loc.join("countries_l_english.yml"),
        "\u{feff}l_english:\n GER:0 \"Germany\"\n GER_ADJ:0 \"German\"\n JAP:0 \"Japan\"\n JAP_ADJ:0 \"Japanese\"\n",
    )
    .unwrap();
    std::fs::create_dir_all(game.path().join("interface")).unwrap();
    game
}

fn harness_with_game(game: &Path) -> Harness {
    let dir = temp_project("[defaults]\nprovider = \"openai\"\n");
    let fixture = Arc::new(FixtureTransport::new());
    let auth = dir.path().join("chatgpt-auth.json").display().to_string();
    let game_s = game.display().to_string();
    let env = MapEnv::from_pairs(&[KEY, ("HOI4_GAME_DIR", &game_s), ("HOI4_IMAGEGEN_CHATGPT_AUTH", &auth)]);
    let engine = Engine::open(dir.path(), Arc::new(env), fixture.clone(), Arc::new(FixedClock(1_793_404_800)), RunMode::Cli).unwrap();
    Harness { dir, engine, fixture }
}

fn plan(h: &Harness, asset: &str, brief: &str, extra: Value) -> imagegen_core::plan::Plan {
    let mut req = json!({"family": "focus", "feature_slug": "f", "asset": asset, "brief": brief, "provider": "openai", "quality": "low"});
    for (k, v) in extra.as_object().unwrap() {
        req[k] = v.clone();
    }
    h.engine.plan(serde_json::from_value(req).unwrap()).unwrap()
}

fn sent(p: &imagegen_core::plan::Plan) -> Vec<String> {
    p.style_sources.as_ref().unwrap().chosen.iter().filter(|c| c.sent_to_provider).map(|c| c.path.rsplit('/').next().unwrap().to_string()).collect()
}

/// Mean pairwise Jaccard overlap of sets.
fn mean_overlap(sets: &[BTreeSet<String>]) -> f64 {
    let mut total = 0.0;
    let mut pairs = 0.0;
    for i in 0..sets.len() {
        for j in i + 1..sets.len() {
            let inter = sets[i].intersection(&sets[j]).count() as f64;
            let union = sets[i].union(&sets[j]).count() as f64;
            total += if union > 0.0 { inter / union } else { 1.0 };
            pairs += 1.0;
        }
    }
    total / pairs
}

